package main

import (
	"regexp"
	"strings"
)

type Rule struct {
	Pattern *regexp.Regexp
	Type    TokenType
}

type Lexer struct {
	Rules []Rule
}

func NewLexer(rules []Rule) *Lexer {
	return &Lexer{Rules: rules}
}

func (l *Lexer) Lex(content string) []Token {
	var tokens []Token
	for len(content) > 0 {
		matched := false
		for _, rule := range l.Rules {
			loc := rule.Pattern.FindStringIndex(content)
			if loc != nil && loc[0] == 0 {
				tokens = append(tokens, Token{Type: rule.Type, Value: content[:loc[1]]})
				content = content[loc[1]:]
				matched = true
				break
			}
		}
		if !matched {
			tokens = append(tokens, Token{Type: Text, Value: string(content[0])})
			content = content[1:]
		}
	}
