{"command":"cat <<'EOF' > style.go
package main

import "fmt"

type StyleEntry struct {
	Color string // hex or ANSI
	Bold  bool
}

type Style map[TokenType]StyleEntry

var MonokaiStyle = Style{
	KeywordNamespace: {"#f92672", false},
	Keyword:          {"#66d9ef", false},
	NameFunction:     {"#a6e22e", false},
	LiteralStringDouble: {"#e6db74", false},
    LiteralStringSingle: {"#e6db74", false},
	NameBuiltin:      {"#a6e22e", false}, // In reality it might be different but it looks close
    NameNamespace:    {"#f8f8f2", false},
    Punctuation:      {"#f8f8f2", false},
    Text:             {"#f8f8f2", false},
}

func formatTerminal16m(tokens []Token, style Style) {
	for _, token := range tokens {
		entry, ok := style[token.Type]
		if ok && entry.Color != "" {
			r, g, b := hexToRGB(entry.Color)
			fmt.Printf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", r, g, b, token.Value)
		} else {
			fmt.Print(token.Value)
		}
	}
}

func hexToRGB(h string) (int, int, int) {
	var r, g, b int
	fmt.Sscanf(h, "#%02x%02x%02x", &r, &g, &b)
	return r, g, b
}

func formatTerminal(tokens []Token, style Style) {
    // Simple version of terminal formatter using 8/16 colors
    for _, token := range tokens {
        color := getSimpleColor(token.Type)
        if color != "" {
            fmt.Printf("\x1b[1m\x1b[%sm%s\x1b[0m", color, token.Value)
        } else {
            fmt.Print(token.Value)
        }
    }
}

func getSimpleColor(t TokenType) string {
    switch t {
    case KeywordNamespace: return "31" // Red
    case Keyword: return "36" // Cyan
    case NameFunction: return "33" // Yellow (Wait, original was 33 for hello)
    case LiteralStringDouble, LiteralStringSingle: return "37" // White
    case NameBuiltin: return "37" // White
    }
    return ""
}
