package main

import (
	"regexp"
)

type Rule struct {
	Pattern *regexp.Regexp
	Type    TokenType
}

type Lexer struct {
	Rules []Rule
}

func NewLexer(rules []Rule) *Lexer {
	return &Lexer{Rules: rules}
}

func (l *Lexer) Lex(content string) []Token {
	var tokens []Token
	for len(content) > 0 {
		matched := false
		for _, rule := range l.Rules {
			loc := rule.Pattern.FindStringIndex(content)
			if loc != nil && loc[0] == 0 {
				tokens = append(tokens, Token{Type: rule.Type, Value: content[:loc[1]]})
				content = content[loc[1]:]
				matched = true
				break
			}
		}
		if !matched {
			tokens = append(tokens, Token{Type: Text, Value: string(content[0])})
			content = content[1:]
		}
	}
	return tokens
}

var pythonRules = []Rule{
	{regexp.MustCompile(`^import\b`), KeywordNamespace},
	{regexp.MustCompile(`^def\b`), Keyword},
	{regexp.MustCompile(`^print\b`), NameBuiltin},
	{regexp.MustCompile(`^"[^"]*"`), LiteralStringDouble},
	{regexp.MustCompile(`^'[^']*'`), LiteralStringSingle},
	{regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*`), Name},
	{regexp.MustCompile(`^[0-9]+`), LiteralNumberInteger},
	{regexp.MustCompile(`^\s+`), Text},
    {regexp.MustCompile(`^[\(\)\:\[\]\,\.]`), Punctuation},
	{regexp.MustCompile(`^[\+\-\*\/\%\=\!\<\>]+`), Operator},
}

func lexPython(content string) []Token {
	l := NewLexer(pythonRules)
	tokens := l.Lex(content)
    for i := 0; i < len(tokens); i++ {
        if tokens[i].Type == Name {
            if i > 0 && (tokens[i-1].Value == "def " || (i > 1 && tokens[i-2].Value == "def" && tokens[i-1].Type == Text)) {
                tokens[i].Type = NameFunction
            } else if i > 0 && (tokens[i-1].Type == KeywordNamespace && i < len(tokens)-1) {
                // simple heuristic for NameNamespace
                tokens[i].Type = NameNamespace
            } else if i > 1 && tokens[i-2].Type == KeywordNamespace && tokens[i-1].Type == Text {
                tokens[i].Type = NameNamespace
            }
        }
    }
    return tokens
}
EOF
"}

