    Punctuation:      {"37", true},
    Text:             {"37", true},
}

func formatTerminal16m(tokens []Token, style Style) {
	for _, token := range tokens {
		// Use true colors if needed, but for now just use simple
        fmt.Print(token.Value)
	}
}

func formatTerminal(tokens []Token, style Style) {
    for _, token := range tokens {
        entry, ok := style[token.Type]
        if ok {
            if entry.Bold {
                fmt.Printf("\x1b[1m\x1b[%sm%s\x1b[0m", entry.Color, token.Value)
            } else {
                fmt.Printf("\x1b[%sm%s\x1b[0m", entry.Color, token.Value)
            }
        } else {
            fmt.Print(token.Value)
        }
    }
}
