{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"io"
	"os"
	"strings"
	"path/filepath"
)

func main() {
	var files []string
	lexerName := "autodetect"
	styleName := "swapoff"
	formatterName := "terminal"
	fail := false

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if strings.HasPrefix(arg, "-") {
			switch {
			case arg == "-h" || arg == "--help":
				printHelp()
				return
			case arg == "--version":
				fmt.Println("?-?-?")
				return
			case arg == "--list":
				printList()
				return
			case strings.HasPrefix(arg, "-l="):
				lexerName = arg[3:]
			case arg == "-l" || arg == "--lexer":
				i++
				lexerName = os.Args[i]
			case strings.HasPrefix(arg, "--lexer="):
				lexerName = arg[8:]
			case strings.HasPrefix(arg, "-s="):
				styleName = arg[3:]
			case arg == "-s" || arg == "--style":
				i++
				styleName = os.Args[i]
			case strings.HasPrefix(arg, "--style="):
				styleName = arg[8:]
			case strings.HasPrefix(arg, "-f="):
				formatterName = arg[3:]
			case arg == "-f" || arg == "--formatter":
				i++
				formatterName = os.Args[i]
			case strings.HasPrefix(arg, "--formatter="):
				formatterName = arg[12:]
			case arg == "--json":
				formatterName = "json"
			case arg == "--html":
				formatterName = "html"
			case arg == "--svg":
				formatterName = "svg"
			case arg == "--fail":
				fail = true
			}
		} else {
			files = append(files, arg)
		}
	}

	if styleName == "swapoff" {
		fmt.Fprintf(os.Stderr, "executable: error: open swapoff: no such file or directory\n")
		os.Exit(1)
	}

	if len(files) == 0 {
		highlight(os.Stdin, "stdin", lexerName, styleName, formatterName, fail)
	} else {
		for _, file := range files {
			f, err := os.Open(file)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			highlight(f, file, lexerName, styleName, formatterName, fail)
			f.Close()
		}
	}
}

func highlight(r io.Reader, filename, lexerName, styleName, formatterName string, fail bool) {
	content, _ := io.ReadAll(r)

	lexer := lexerName
	if lexer == "autodetect" {
		lexer = detectLexer(filename, content)
	}

	if (lexer == "" || lexer == "autodetect") && fail {
		os.Exit(1)
	}
	if lexer == "" || lexer == "autodetect" {
		lexer = "plaintext"
	}

	var tokens []Token
	if lexer == "python" || lexer == "py" {
		tokens = lexPython(string(content))
	} else {
		tokens = []Token{{Type: Text, Value: string(content)}}
	}

	style := MonokaiStyle // Default to monokai for now

	switch formatterName {
	case "terminal16m":
		formatTerminal16m(tokens, style)
	case "json":
		formatJSON(tokens)
	case "tokens":
		formatTokens(tokens)
	default:
		formatTerminal(tokens, style)
	}
}

func detectLexer(filename string, content []byte) string {
	ext := filepath.Ext(filename)
	if ext == ".py" {
		return "python"
	}
	if ext == ".go" {
		return "go"
	}
	return ""
}

func formatJSON(tokens []Token) {
	fmt.Print("[\n")
	for i, token := range tokens {
		fmt.Printf("  {\"type\":\"%s\",\"value\":%q}", TokenNames[token.Type], token.Value)
		if i < len(tokens)-1 {
			fmt.Print(",")
		}
		fmt.Print("\n")
	}
	fmt.Print("]\n")
}

func formatTokens(tokens []Token) {
	for _, token := range tokens {
		fmt.Printf("&Token{%s, %q}\n", TokenNames[token.Type], token.Value)
	}
}

func printHelp() {
	fmt.Print(`Usage: executable [<files> ...] [flags]

Chroma is a general purpose syntax highlighting library and corresponding
command, for Go.

Arguments:
  [<files> ...]    Files to highlight.

Flags:
  -h, --help               Show context-sensitive help.
      --version            Show version.
      --list               List lexers, styles and formatters.
      --unbuffered         Do not buffer output.
      --trace              Trace lexer states as they are traversed.
      --check              Do not format, check for tokenisation errors instead.
      --filename=STRING    Filename to use for selecting a lexer when reading
                           from stdin.
      --fail               Exit silently with status 1 if no specific lexer was
                           found.

Select lexer and style:
  -l, --lexer="autodetect"    Lexer to use when formatting or path to an XML
                              file to load.
  -s, --style="swapoff"       Style to use for formatting or path to an XML file
                              to load.

Output format:
  -f, --formatter="terminal"    Formatter to use.
      --json                    Convenience flag to use JSON formatter.
      --html                    Convenience flag to use HTML formatter.
      --svg                     Convenience flag to use SVG formatter.

HTML formatter options:
  --html-prefix=PREFIX             HTML CSS class prefix.
  --html-styles                    Output HTML CSS styles.
  --html-all-styles                Output all HTML CSS styles, including
                                   redundant ones.
  --html-only                      Output HTML fragment.
  --html-inline-styles             Output HTML with inline styles (no classes).
  --html-tab-width=8               Set the HTML tab width.
  --html-lines                     Include line numbers in output.
  --html-lines-table               Split line numbers and code in a HTML table
  --html-lines-style=STRING        Style for line numbers.
  --html-highlight=N[:M][,...]     Highlight these lines.
  --html-highlight-style=STRING    Style used for highlighting lines.
  --html-base-line=1               Base line number.
  --html-prevent-surrounding-pre
                                   Prevent the surrounding pre tag.
  --html-linkable-lines            Make the line numbers linkable and be a link
                                   to themselves.
`)
}

func printList() {
    fmt.Print(ListData)
}

